create or replace function public.update_circle_settings(target_circle_id uuid,circle_description text,circle_visibility text,circle_rules text) returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from public.circle_members where circle_id=target_circle_id and profile_id=auth.uid()and status='active'and role in('owner','moderator'))then raise exception 'circle moderator required';end if;if circle_visibility not in('public','private')then raise exception 'invalid visibility';end if;update public.circles set description=trim(circle_description),visibility=circle_visibility,rules=coalesce(circle_rules,'')where id=target_circle_id;end$$;
create or replace function public.create_circle_request(target_circle_id uuid,payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare new_id uuid;skill text;member_id uuid;circle_name text;begin if not exists(select 1 from public.circle_members where circle_id=target_circle_id and profile_id=auth.uid()and status='active')then raise exception 'active membership required';end if;select name into circle_name from public.circles where id=target_circle_id;insert into public.work_requests(owner_id,title,description,kind,stage,location_text,urgency_text,cash_budget_cents,visibility,exchange_modes,exchange_summary,constraints,location_visibility,circle_id)values(auth.uid(),trim(payload->>'title'),trim(payload->>'description'),(payload->>'kind')::public.work_kind,case when coalesce((payload->>'publish')::boolean,true)then'open'::public.work_stage else'draft'::public.work_stage end,payload->>'location',payload->>'urgency',nullif(payload->>'cash_budget_cents','')::bigint,'circle',coalesce(array(select jsonb_array_elements_text(payload->'exchange_modes'))::public.exchange_mode[],array['barter'::public.exchange_mode]),payload->>'exchange_summary',payload->>'constraints','participants',target_circle_id)returning id into new_id;for skill in select jsonb_array_elements_text(coalesce(payload->'skills','[]'::jsonb))loop insert into public.work_request_skills(request_id,skill)values(new_id,skill);end loop;for member_id in select profile_id from public.circle_members where circle_id=target_circle_id and status='active'and profile_id<>auth.uid()loop perform public.notify_user(member_id,'network','New work in '||circle_name,trim(payload->>'title'),new_id,null);end loop;return new_id;end$$;
revoke all on function public.update_circle_settings(uuid,text,text,text) from public;grant execute on function public.update_circle_settings(uuid,text,text,text) to authenticated;
